/**
 * Drill-down from a Touchless KPI tile to the documents behind its number
 * (DOCB-14197).
 *
 * A rate on a dashboard is only actionable if the reader can get to the rows it
 * was computed from. `GET /document/dashboards` accepts three params for that:
 *
 *   * `touchless_bucket`         — one of TOUCHLESS_DRILLDOWN_BUCKETS. The
 *                                  backend answers 422 to anything else, so an
 *                                  unrecognised value is dropped here rather
 *                                  than forwarded.
 *   * `touchless_undiagnosed`    — the fifth tile's "N without a known cause".
 *                                  NOT a bucket: it is
 *                                  `first_blocking_reason_code == UNKNOWN`,
 *                                  which cuts across buckets.
 *   * `touchless_window_days`    — 7, 30 or 90, so the list covers the same window
 *                                  the tile counted.
 *
 * Every one of the five tiles, and the dashboard side that has to read the
 * params back off the URL, goes through this module. Five call sites each
 * spelling the param names themselves is five places for a rename to rot.
 */

/** Buckets the backend will accept for `touchless_bucket`. */
export const TOUCHLESS_DRILLDOWN_BUCKETS = [
  'PURE_TOUCHLESS',
  'AP_TOUCHLESS',
  'AP_ASSISTED',
  'PROCESS_EXCEPTION',
  'IN_PROGRESS',
  'NOT_ELIGIBLE',
] as const;

export type TouchlessDrilldownBucket =
  (typeof TOUCHLESS_DRILLDOWN_BUCKETS)[number];

/**
 * Windows the backend will accept for `touchless_window_days`.
 *
 * The panel's own period toggle also offers 7d (TOUCHLESS_PERIOD_OPTIONS), for
 * which the endpoint has no value — see `touchlessWindowDays`.
 */
// 7 as well: the panel's picker offers it and the endpoint accepts it. The
// filter is a plain date range, not a materialised cluster window — that
// distinction is what made an earlier version widen 7 to 30 and answer a
// seven-day click with thirty days of documents.
export const TOUCHLESS_DRILLDOWN_WINDOWS = [7, 30, 90] as const;

export type TouchlessDrilldownWindow =
  (typeof TOUCHLESS_DRILLDOWN_WINDOWS)[number];

/** Param names, in one place. */
export const TOUCHLESS_BUCKET_PARAM = 'touchless_bucket';
export const TOUCHLESS_UNDIAGNOSED_PARAM = 'touchless_undiagnosed';
export const TOUCHLESS_WINDOW_PARAM = 'touchless_window_days';
/**
 * Supplier scope (DOCB-14285). The supplier DETAIL page's tiles count one
 * supplier's documents, so their links must too — without this the list
 * behind "12 process exceptions for ACME" is every process exception in the
 * org, which is a larger number under a smaller label.
 *
 * Never a scope on its own: `touchless_supplier_key` alone would silently
 * narrow an ordinary dashboard visit to one supplier, so it only rides along
 * with a bucket or the undiagnosed cut.
 */
export const TOUCHLESS_SUPPLIER_PARAM = 'touchless_supplier_key';

/** The document list. `/dashboard`, not `/documents` (src/router/routes.ts). */
export const TOUCHLESS_DRILLDOWN_PATH = '/dashboard';

/** Router location for a drill-down, in the shape `$router.resolve` wants. */
export interface TouchlessDrilldownLocation {
  path: typeof TOUCHLESS_DRILLDOWN_PATH;
  query: Record<string, string>;
}

/** What a tile asks for. */
export interface TouchlessDrilldownRequest {
  /** The panel's selected doc type, if any. Keeps the list as narrow as the tile. */
  docType?: string | null;
  /** Bucket the tile counts. Omit for the undiagnosed tile. */
  bucket?: TouchlessDrilldownBucket;
  /** The undiagnosed tile — mutually exclusive with `bucket`. */
  undiagnosed?: boolean;
  /** Supplier the tile counted, for the supplier detail page's tiles. */
  supplierKey?: string | null;
  /** The panel's current period ('7d' | '30d' | '90d'). */
  period?: unknown;
  /**
   * Documents behind the number. Zero means there is no list to open, and a
   * link to an empty list is worse than no link, so the builder answers null.
   */
  count?: number | null;
}

/** Params recovered from a URL, already validated against the contract. */
export interface TouchlessDrilldownParams {
  bucket: TouchlessDrilldownBucket | null;
  undiagnosed: boolean;
  windowDays: TouchlessDrilldownWindow | null;
  supplierKey: string | null;
}

export const EMPTY_TOUCHLESS_DRILLDOWN_PARAMS: TouchlessDrilldownParams = {
  bucket: null,
  undiagnosed: false,
  windowDays: null,
  supplierKey: null,
};

function isDrilldownBucket(value: unknown): value is TouchlessDrilldownBucket {
  return (
    typeof value === 'string' &&
    (TOUCHLESS_DRILLDOWN_BUCKETS as readonly string[]).includes(value)
  );
}

function isDrilldownWindow(value: unknown): value is TouchlessDrilldownWindow {
  return (
    typeof value === 'number' &&
    (TOUCHLESS_DRILLDOWN_WINDOWS as readonly number[]).includes(value)
  );
}

/**
 * The panel period as a window the endpoint accepts.
 *
 * The endpoint takes 30 or 90 only, while the panel's toggle also offers 7d.
 * 7d therefore widens to 30: sending 7 would be a 422 and a broken link, and
 * omitting the window entirely would leave the list on whatever the backend
 * defaults to — an invisible mismatch instead of a documented one. The tile's
 * own count still comes from the 7-day summary, so on a 7d view the list is a
 * superset of the number that was clicked.
 */
export function touchlessWindowDays(period: unknown): TouchlessDrilldownWindow {
  // The panel offers 7d as well, and the backend accepts it: the filter is a
  // plain date range, not a materialised cluster window. Widening 7 to 30
  // here would answer a click on the 7-day view with thirty days of
  // documents — a list quietly larger than the number on the tile, which is
  // the one thing this link must never do.
  const days = Number.parseInt(String(period ?? ''), 10);
  if (!Number.isFinite(days)) return 30;
  if (days <= 7) return 7;
  if (days <= 30) return 30;
  return 90;
}

/**
 * Router location for one tile, or null when the tile must not be a link.
 *
 * Null on a zero count, and null when the request names neither a bucket nor
 * the undiagnosed cut — an unscoped `/dashboard?touchless_window_days=30`
 * would silently narrow the whole document list to a window the user never
 * asked for.
 */
export function buildTouchlessDrilldownLocation(
  request: TouchlessDrilldownRequest,
): TouchlessDrilldownLocation | null {
  const { bucket, undiagnosed, period, count } = request;

  if (count !== undefined && (count === null || count <= 0)) return null;

  const query: Record<string, string> = {};
  if (undiagnosed) {
    query[TOUCHLESS_UNDIAGNOSED_PARAM] = 'true';
  } else if (isDrilldownBucket(bucket)) {
    query[TOUCHLESS_BUCKET_PARAM] = bucket;
  } else {
    return null;
  }

  query[TOUCHLESS_WINDOW_PARAM] = String(touchlessWindowDays(period));

  // `store.bucketCount()` is doc-type-scoped when the panel has a doc type
  // selected, so the link must carry it too — otherwise the list is broader
  // than the number that was clicked. This rides the dashboard's OWN
  // `doc_type` param; no new contract is needed for it.
  const docType =
    typeof request.docType === 'string' ? request.docType.trim() : '';
  if (docType) {
    query.doc_type = docType;
  }

  // Supplier-scoped tiles (DOCB-14285). Same rule as `doc_type`: the link has
  // to be as narrow as the number it sits under.
  const supplierKey =
    typeof request.supplierKey === 'string' ? request.supplierKey.trim() : '';
  if (supplierKey) {
    query[TOUCHLESS_SUPPLIER_PARAM] = supplierKey;
  }

  return { path: TOUCHLESS_DRILLDOWN_PATH, query };
}

/** First value of a query entry — `?a=1&a=2` arrives as an array. */
function firstValue(value: unknown): unknown {
  return Array.isArray(value) ? value[0] : value;
}

/**
 * Read the drill-down params back off a route query, validated.
 *
 * Hand-edited and stale URLs reach this: a bucket the build has never heard of
 * is dropped rather than forwarded (the backend answers 422, which would
 * surface as "error fetching invoices" on an otherwise healthy dashboard), and
 * so is a window that is not 30 or 90.
 */
export function extractTouchlessDrilldownParams(
  query: Record<string, unknown> | null | undefined,
): TouchlessDrilldownParams {
  if (!query) return { ...EMPTY_TOUCHLESS_DRILLDOWN_PARAMS };

  const rawBucket = firstValue(query[TOUCHLESS_BUCKET_PARAM]);
  const rawUndiagnosed = firstValue(query[TOUCHLESS_UNDIAGNOSED_PARAM]);
  const rawWindow = firstValue(query[TOUCHLESS_WINDOW_PARAM]);
  const rawSupplier = firstValue(query[TOUCHLESS_SUPPLIER_PARAM]);

  const undiagnosed =
    rawUndiagnosed === true ||
    (typeof rawUndiagnosed === 'string' &&
      ['true', '1'].includes(rawUndiagnosed.trim().toLowerCase()));

  const windowDays = Number.parseInt(String(rawWindow ?? ''), 10);

  const supplierKey =
    typeof rawSupplier === 'string' && rawSupplier.trim()
      ? rawSupplier.trim()
      : null;

  return {
    bucket: isDrilldownBucket(rawBucket) ? rawBucket : null,
    undiagnosed,
    windowDays: isDrilldownWindow(windowDays) ? windowDays : null,
    supplierKey,
  };
}

/** Does this route carry a usable drill-down scope? */
export function hasTouchlessDrilldown(
  query: Record<string, unknown> | null | undefined,
): boolean {
  const params = extractTouchlessDrilldownParams(query);
  return params.bucket !== null || params.undiagnosed;
}

/**
 * The params as an `&key=value` fragment for the `/document/dashboards` query
 * string, which `dashboard.store.ts` assembles by string concatenation.
 *
 * Empty string when there is no scope — including when only a window survived
 * validation, so a leftover `?touchless_window_days=90` cannot narrow an
 * ordinary dashboard visit.
 */
export function touchlessDrilldownQueryString(
  params: TouchlessDrilldownParams,
): string {
  if (!params.bucket && !params.undiagnosed) return '';

  let query = '';
  if (params.undiagnosed) {
    query += `&${TOUCHLESS_UNDIAGNOSED_PARAM}=true`;
  } else if (params.bucket) {
    query += `&${TOUCHLESS_BUCKET_PARAM}=${encodeURIComponent(params.bucket)}`;
  }
  if (params.windowDays !== null) {
    query += `&${TOUCHLESS_WINDOW_PARAM}=${params.windowDays}`;
  }
  // Only ever alongside a bucket / the undiagnosed cut — the early return
  // above already guaranteed one of them is present.
  if (params.supplierKey) {
    query += `&${TOUCHLESS_SUPPLIER_PARAM}=${encodeURIComponent(
      params.supplierKey,
    )}`;
  }
  return query;
}

/** `touchlessDrilldownQueryString` straight from a route query. */
export function touchlessDrilldownQueryStringFromRoute(
  query: Record<string, unknown> | null | undefined,
): string {
  return touchlessDrilldownQueryString(extractTouchlessDrilldownParams(query));
}
